{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C47"],
      "claim": "Laninamivir octanoate, a lipophilic ester prodrug, has only 15% oral bioavailability in humans, supporting that esterified lipophilic drugs can have low systemic F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Felodipine has an absolute oral bioavailability of 15% in humans, showing that lipophilic drugs subject to first-pass metabolism can fall below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Tegaserod has an absolute bioavailability of approximately 10% in healthy volunteers, another example of a drug with low oral systemic availability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "DVAS, a long-chain dodecyl ester of a dipeptide, has an average oral bioavailability of 60% in healthy volunteers, indicating that some lipid ester/peptide conjugates are well absorbed; however, it lacks the beta-lactone and local GI-targeting design of the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is orlistat, a beta-lactone pancreatic lipase inhibitor designed to act locally in the GI tract; its systemic absorption is negligible. Multiple low-F lipophilic drug analogues support F < 20%, while the one high-F lipid ester analogue is not mechanistically transferable.",
  "evidence_gaps": [
    "No direct bioavailability measurement for the query molecule in the provided records.",
    "No analogue with a beta-lactone ring or lipase-inhibitor mechanism is present; structural transferability is limited.",
    "The high-F lipid ester analogue (DVAS) suggests that lipid ester structure alone does not predict low F, but the query's beta-lactone and local GI action are not captured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

